parameters.query:
SELECT ally_ui_startseite($1::text) AS r,
  -- Startseite (B9, Stefan 29.10.2026, „a und c“): Auswahl der eigenen Startseite nur beim Anordnen ($2 = '1')
  CASE WHEN $2::text = '1' THEN ally_startseite_ui($1::text) END AS st;

