// Startseite (ALLY 22, Stefan 19.10.2026; Talents-Karten Punkt 5f, 21.10.2026; Block „Überblick“ je Person, Migration 78): Kacheln/Liste, Gruppen (eigene zuerst), Anordnen-Modus (?anordnen=1), Zahnrad je Kachel zu den Einstellungen der Funktion.
// Daten aus ally_ui_startseite (nur erlaubte Funktionen, Zustand je Person). Liefert nur die Seitenbeschreibung (JSON), kein HTML.
// Punkt 7a (Stefan 21.10.2026): Auf jeder Kachel steht wie in ALLY 8 der aktuelle Stand mit Zahl statt einer festen Beschreibung (Texte 1:1 aus ALLY 8 "Startseite einsetzen").
// Stand aus "Stand laden": ally_web_arbeit (wie ALLY 8, Feld a), talents_kachel (Talents, wie ALLY 8 am 18.10.), Kennzahlen aus talents_kampagnen_ui (Kampagnen, neu).
// Alle drei sind auf die Sitzung und die Rechte der Person beschränkt. Fehlt der Stand (Fehler oder Paket aus), bleibt die Beschreibung der Funktion.
// Schlussprüfung (Migration 94): Kachel „Verkaufsberichte“ mit Zahl der Berichte und nächstem Termin (shopify_kachel, Feld sh).
const E = $('Start').first().json;
const D = $('Startseite laden').first().json.r || {};
const F = E.funktion || {};
// Stefan 23.10.2026, 20:23 (Startseite langsam): ?schnell=1 lädt ohne die Talents-Zahlen ($2, $4, $5 in „Stand laden“); deren Stellen kommen als Platzhalter (laedt),
// die App holt die vollständige Seite gleich danach im Hintergrund. Inhalt und Texte wie bisher.
const SCHNELL = String((E.parameter || {}).anordnen || '') !== '1' && String((E.parameter || {}).schnell || '') === '1';
if (D.ok !== true) {
  return [{ json: { inhalt: { seite: { schluessel: 'start', art: 'funktion', titel: String(F.name || '') },
    bloecke: [{ typ: 'hinweis', ton: 'warn', text: 'Die Startseite konnte nicht geladen werden. Bitte die Seite neu laden.' }] } } }];
}
let ST = {}; try { ST = $('Stand laden').first().json || {}; } catch (e) { ST = {}; }
const ob = x => x && typeof x === 'object' && !Array.isArray(x) ? x : null;
const A = ob(ST.a) || {}, TK = ob(ST.tk), KP = ob(ST.kp), DE = ob(ST.de) || {};
const zahlWort = (n, eins, mehr) => n === 1 ? '1 ' + eins : n + ' ' + mehr;
const N = v => Number(v) || 0;
// Stand je Kachel: { status, zahl, ton } – nur gesetzte Felder ersetzen die Beschreibung
const STAND = {
  belege: () => { const b = ob(A.belege); if (!b) return null; const neu = N(b.neu), kl = N(b.klaerungen), fe = N(b.fehler);
    return { status: b.laeuft ? 'Wird gerade verbucht' : [neu === 1 ? 'neuer Beleg' : 'neue Belege', kl ? zahlWort(kl, 'offene Frage', 'offene Fragen') : '', fe ? zahlWort(fe, 'Fehler', 'Fehler') : ''].filter(Boolean).join(' · '),
      zahl: String(neu), ton: fe > 0 ? 'warn' : '' }; },
  zeiterfassung: () => { const z = ob(A.abgleich); if (!z) return null;
    return { status: z.laeuft ? 'Der Abgleich läuft gerade' : z.zuletzt ? 'Letzter Abgleich' + (z.alt ? ', länger her als üblich' : '') : 'Noch kein Abgleich vermerkt',
      zahl: z.zuletzt && !z.laeuft ? String(z.zuletzt).replace(/^(\d\d\.\d\d\.)\d{4},.*$/, '$1') : '', ton: !z.laeuft && z.alt ? 'warn' : '' }; },
  marketing: () => { const mk = ob(A.marketing); if (!mk) return null; const th = Array.isArray(mk.themen) ? mk.themen : [], ia = N(mk.in_arbeit), ew = N(mk.entwurf);
    return { status: mk.laeuft ? 'Themenvorschläge sind unterwegs' : [th.length === 1 ? 'offenes Thema' : 'offene Themen', ia ? zahlWort(ia, 'Beitrag', 'Beiträge') + ' in Arbeit' : '',
      ew ? zahlWort(ew, 'Entwurf', 'Entwürfe') + ' zur Freigabe' : '', N(mk.geplant) ? zahlWort(N(mk.geplant), 'Post', 'Posts') + ' geplant' : ''].filter(Boolean).join(' · '),
      zahl: mk.laeuft ? '' : String(th.length) }; },
  kundenueberblick: () => Array.isArray(A.kunden) ? { status: A.kunden.length === 1 ? 'Eintrag der Kundschaft' : 'Einträge der Kundschaft', zahl: String(A.kunden.length) } : null,
  monatsbericht: () => ({ status: 'Zeiten aus Papierkram als PDF je Kundschaft und Monat' }),
  'morgen-briefing': () => { const br = ob(A.briefing); if (!br) return null;
    return { status: !br.an ? 'Für dich ausgeschaltet' : br.laeuft ? 'Unterwegs in den Chat' : 'täglich' + (br.heute ? ', heute schon geschickt' : ''),
      zahl: br.an ? String(br.uhrzeit || '') : '', ton: !br.an ? 'warn' : '' }; },
  'mail-assistent': () => { const m = ob(A.mails); if (!m || N(m.postfaecher) <= 0) return null; const n = N(m.angebote);
    return { status: m.entwuerfe ? (n === 1 ? 'Antwortvorschlag offen' : 'Antwortvorschläge offen') : 'Mail-Log', zahl: m.entwuerfe ? String(n) : '' }; },
  kalender: () => { const k = ob(A.kalender); if (!k) return null;
    return { status: k.hinterlegt ? 'Termine ansehen und anlegen' : 'Noch kein Kalender hinterlegt', ton: k.hinterlegt ? '' : 'warn' }; },
  projektbudgets: () => ob(A.budgets) ? { status: 'Laufende Projekte mit Budget' } : null,
  'system-mails': () => { const s = ob(A.systemmails); return s ? { status: 'in den letzten 7 Tagen', zahl: String(N(s.woche)) } : null; },
  // Ally fragen: kein Stand. Der ALLY-8-Text „Noch kein Chat eingerichtet“ passt nicht mehr, weil die Antwort seit BA10 auch auf der Seite kommt; die Beschreibung bleibt.
  // Talents wie die ALLY-8-Kachel vom 18.10.: Anzahl, Kanäle, Warnung bei ablaufenden Verbindungen, neue Beiträge seit gestern
  talents: () => { if (!TK || TK.ok !== true || TK.anzeigen !== true) return null; const nt = N(TK.anzahl_talents), nk = N(TK.anzahl_kanaele);
    if (!nt) return { status: String(TK.kopf || 'Noch keine Talents'), zahl: '0' };
    const w = ob(TK.warnung), nb = ob(TK.neue_beitraege);
    return w && w.text ? { status: String(w.text), zahl: String(nt), ton: 'warn' }
      : { status: [nk === 1 ? '1 Kanal' : nk + ' Kanäle', nb && nb.text ? String(nb.text) : ''].filter(Boolean).join(' · '), zahl: String(nt) }; },
  // Kampagnen (neu, ALLY 8 hatte keine Kachel): laufende Kampagnen, überfällige Deadlines (Warnung), Deadlines in 7 Tagen, offene Freigaben
  kampagnen: () => { if (!KP) return null; const l = N(KP.laufend), g = N(KP.geplant), ue = N(KP.ueberfaellig), d7 = N(KP.deadlines_7), fr = N(KP.freigaben_offen);
    return { status: [l ? (l === 1 ? 'Kampagne läuft' : 'Kampagnen laufen') : g ? zahlWort(g, 'Kampagne geplant', 'Kampagnen geplant') : 'Keine laufenden Kampagnen',
      ue ? zahlWort(ue, 'Deadline überfällig', 'Deadlines überfällig') : '', d7 ? zahlWort(d7, 'Deadline', 'Deadlines') + ' in 7 Tagen' : '',
      fr ? zahlWort(fr, 'Freigabe offen', 'Freigaben offen') : ''].filter(Boolean).join(' · '), zahl: String(l), ton: ue > 0 ? 'warn' : '' }; },
  // Verkaufsberichte: „2 Berichte · nächster Versand 1.11.“ (ohne Zeitplan: „kein Zeitplan“)
  verkaufsberichte: () => { const v = ob(ST.sh); if (!v || v.ok !== true) return null; const n = N(v.berichte);
    if (!n) return { status: 'Noch keine Berichte', zahl: '0' };
    return { status: [n === 1 ? 'Bericht' : 'Berichte', v.naechster ? (v.art === 'ablage' ? 'nächste Ablage ' : 'nächster Versand ') + String(v.naechster) : 'kein Zeitplan'].join(' · '), zahl: String(n) }; }
};
// Migration 78 (Stefan 21.10.2026, 19:47/19:48): fester Block „Überblick“ oben auf der Startseite. Was darin steht, wählt jede Person selbst (Zahnrad „Startseite anordnen“).
// Die Bausteine liefert ally_ui_startseite (Feld ueberblick): nur erlaubte (Paket gebucht und Recht), in der Reihenfolge der Person, an/aus. Ohne Auswahl sind alle an.
// Ist nichts an oder fehlen die Daten aller gewählten Bausteine, gibt es keinen Block. Zahlenkacheln (art kennzahl) stehen oben, Karten (art karte) darunter, jeweils in der gewählten Reihenfolge.
// Talents-Bausteine wie das ALLY-8-Dashboard (Punkt 5f): 4 Kennzahlen, Handlungsbedarf, Größte Veränderungen, Laufende Kampagnen, Neue Inhalte.
const UB = (Array.isArray(D.ueberblick) ? D.ueberblick : []).filter(b => b && typeof b.schluessel === 'string');
const ueberblickBauen = () => {
  const AN = UB.filter(b => b.an === true);
  if (!AN.length) return null;
  const TU = ob(ST.tu) && ST.tu.ok === true ? ST.tu : null, TKD = TK && TK.ok === true && TK.anzeigen === true ? TK : null, KPL = ob(ST.tkp) && ST.tkp.ok === true ? ST.tkp : null;
  const L = x => Array.isArray(x) ? x : [], tx = w => w && typeof w === 'object' && w.text !== undefined && w.text !== null ? String(w.text) : '–';
  const id9 = v => /^[0-9]{1,9}$/.test(String(v ?? '')) ? Number(v) : null;
  const su = (TU && TU.summe) || {}, zr = (TU && TU.zeitraum) || {};
  const tonV = v => v && v.text && v.text !== '–' ? (v.richtung === 'runter' ? 'warn' : v.richtung === 'hoch' ? 'ok' : '') : '';
  const vText = v => v && v.text && v.text !== '–' ? String(v.text) + ' zum Vorzeitraum' : String(zr.name || 'Letzte 28 Tage');
  const alleT = { seite: 'talents', anker: 'a-alle' };
  const zrKlein = zr.name ? String(zr.name).charAt(0).toLowerCase() + String(zr.name).slice(1) : 'im Zeitraum';
  // Stefan 24.10.2026, 09:29–09:31: Inhalt der geöffneten Zahlenkacheln (details) – kompakt, nichts doppelt, nur vorhandene Daten (ally_start_details, Migration 140)
  const tausend = n => String(Math.round(Number(n) || 0)).replace(/\B(?=(\d{3})+(?!\d))/g, '.');
  const tm = s => { const m = /^([0-9]{4})-([0-9]{2})-([0-9]{2})$/.exec(String(s || '')); return m ? Number(m[3]) + '.' + Number(m[2]) + '.' : ''; };
  const kanalZeilen = () => L(DE.plattformen).map(p => { const v = N(p.verbunden), b = N(p.bald), a = N(p.abgelaufen);
    return { fett: String(p.name || p.plattform || ''), teile: [v ? { text: v + ' verbunden' } : null, b ? { text: b + ' läuft bald ab', ton: 'warn' } : null, a ? { text: a + ' abgelaufen', ton: 'warn' } : null].filter(Boolean) }; });
  const verlauf = (feld, name) => Array.isArray(DE.wochen) ? { art: 'verlauf', titel: name + ' je Woche',
    punkte: L(DE.wochen).map(x => ({ label: tm(x.bis), wert: N(x[feld]), text: x[feld] === null || x[feld] === undefined ? '–' : tausend(x[feld]) })),
    unter: 'Je 7 Tage bis ' + tm((L(DE.wochen).slice(-1)[0] || {}).bis) + ', letzte 8 Wochen. Aus den automatisch abgerufenen Zahlen, ohne manuelle Werte.',
    leer: 'Für einen Verlauf gibt es noch keine Zahlen.' } : null;
  const eintraege = (E, leer) => ({ art: 'zeilen', zeilen: L(E).slice(0, 3).map(e => ({ fett: String(e.wer || ''), text: String(e.betreff || ''), neben: String(e.datum || '') })), leer });
  const BAU = {
    'talents-kennzahlen': () => { if (!TU || !TKD) return null; const fz = Number((su.follower_zuwachs || {}).wert);
      return { kennzahlen: [
        { label: 'Talents', wert: String(N(TKD.anzahl_talents)), neben: zahlWort(N(TKD.anzahl_kanaele), 'verbundener Kanal', 'verbundene Kanäle'), ziel: { seite: 'talents' }, ziel_text: 'Talents öffnen',
          details: Array.isArray(DE.plattformen) ? { art: 'zeilen', zeilen: kanalZeilen(), unter: 'Kanäle je Plattform', leer: 'Noch keine verbundenen Kanäle.' } : undefined },
        { label: 'Reichweite', wert: tx(su.reichweite), neben: vText((su.reichweite || {}).veraenderung), ton: tonV((su.reichweite || {}).veraenderung), ziel: alleT, ziel_text: 'Talents öffnen',
          details: verlauf('reichweite', 'Reichweite') || undefined },
        { label: 'Interaktionen', wert: tx(su.interaktionen), neben: vText((su.interaktionen || {}).veraenderung), ton: tonV((su.interaktionen || {}).veraenderung), ziel: alleT, ziel_text: 'Talents öffnen',
          details: verlauf('interaktionen', 'Interaktionen') || undefined },
        { label: 'Follower-Zuwachs', wert: tx(su.follower_zuwachs), neben: 'Follower gesamt ' + tx(su.follower), ton: fz < 0 ? 'warn' : fz > 0 ? 'ok' : '', ziel: alleT, ziel_text: 'Talents öffnen' }] }; },
    // Handlungsbedarf (höchstens 6, dann „und n weitere“): Verbindungen, Datenimport, Kampagnen ohne Beitrag
    'talents-handlungsbedarf': () => { if (!TKD) return null; const HB = [], W = ob(TKD.warnung) || {};
      if (N(W.anzahl_abgelaufen) > 0) HB.push({ fett: 'Verbindungen', marke: { text: zahlWort(N(W.anzahl_abgelaufen), 'Verbindung abgelaufen', 'Verbindungen abgelaufen'), ton: 'warn' },
        ziel: { seite: 'talents', parameter: { status: 'aufmerksamkeit' }, anker: 'a-alle' } });
      if (N(W.anzahl_bald) > 0) HB.push({ fett: 'Verbindungen', marke: { text: zahlWort(N(W.anzahl_bald), 'Verbindung läuft bald ab', 'Verbindungen laufen bald ab'), ton: 'warn' },
        ziel: { seite: 'talents', parameter: { status: 'aufmerksamkeit' }, anker: 'a-alle' } });
      // 7f (Koordinator 25.10.2026, wie Talents nach Stefans 7e „Direkt zum Prüfen“): direkt in den Datenimport des Talents › „Zur Prüfung“ statt ins Profil › Daten und Notizen
      for (const z of L(TU && TU.zeilen)) if (N(z.zahlen_offen) > 0 && id9(z.talent_id) !== null) HB.push({ fett: String(z.anzeigename || ''),
        marke: { text: 'Datenimport: ' + zahlWort(N(z.zahlen_offen), 'Vorschlag', 'Vorschläge') + ' prüfen' }, ziel: { seite: 'talent', parameter: { id: id9(z.talent_id), w: 'zahlen' }, anker: 'a-pruefung' } });
      for (const k of L(KPL && KPL.zeilen)) if (N(k.talents_ohne_beitrag) > 0 && id9(k.kampagne_id) !== null) HB.push({ fett: String(k.titel || 'Kampagne'),
        marke: { text: zahlWort(N(k.talents_ohne_beitrag), 'Talent', 'Talents') + ' noch ohne Beitrag', ton: 'warn' }, ziel: { seite: 'kampagnen', parameter: { kampagne: id9(k.kampagne_id) } } });
      const hb = HB.slice(0, 6).map(e => Object.assign(e, { text: '', marke_hinten: true, ziel_text: 'Öffnen' }));
      if (HB.length > 6) hb.push({ text: 'und ' + (HB.length - 6) + ' weitere', ziel: { seite: 'talents', anker: 'a-alle' }, ziel_text: 'Alle Talents' });
      return { karte: { ziel: { seite: 'talents' }, ziel_text: 'Talents öffnen', titel: 'Handlungsbedarf', info: 'Verbindungen, Datenimport und Kampagnen, die eine Aktion brauchen.', leer: 'Gerade ist nichts zu tun.', eintraege: hb } }; },
    // Größte Veränderungen (Reichweite gegenüber dem Vorzeitraum, Top 5)
    'talents-veraenderungen': () => { if (!TU) return null;
      const GV = L(TU.zeilen).filter(z => z.veraenderung && z.veraenderung.text && z.veraenderung.text !== '–' && id9(z.talent_id) !== null).slice(0, 5)
        .map(z => ({ text: String(z.anzeigename || ''), trend: { text: String(z.veraenderung.text), richtung: ['hoch', 'runter'].includes(z.veraenderung.richtung) ? z.veraenderung.richtung : 'gleich' },
          ziel: { seite: 'talent', parameter: { id: id9(z.talent_id) } }, ziel_text: 'Öffnen' }));
      return { karte: { ziel: alleT, ziel_text: 'Talents öffnen', titel: 'Größte Veränderungen', info: 'Reichweite ' + zrKlein + ' gegenüber dem Vorzeitraum.', leer: 'Für einen Vergleich gibt es noch zu wenige Zahlen.', eintraege: GV } }; },
    // Laufende Kampagnen mit Fortschritt nach Laufzeit (höchstens 5), kurz wie in ALLY 8 (Ende, Beiträge, Laufzeit)
    'talents-kampagnen': () => { if (!KPL) return null;
      const heute = new Date(), tag = s => { const m = /^([0-9]{4})-([0-9]{2})-([0-9]{2})$/.exec(String(s || '')); return m ? Date.UTC(+m[1], +m[2] - 1, +m[3]) : null; };
      const anteil = k => { const v = tag(k.von_iso), b = tag(k.bis_iso), j = Date.UTC(heute.getUTCFullYear(), heute.getUTCMonth(), heute.getUTCDate()); if (v === null || b === null || b < v) return null;
        return Math.max(0, Math.min(100, Math.round((j - v) / Math.max(1, b - v + 864e5) * 100))); };
      const KZ = L(KPL.zeilen).filter(k => id9(k.kampagne_id) !== null).slice(0, 5);
      const lk = KZ.map(k => { const p = anteil(k);
        return Object.assign({ text: String(k.titel || 'Kampagne'), neben: 'bis ' + String(k.bis || '–') + ' · ' + zahlWort(N(k.anzahl_beitraege), 'Beitrag', 'Beiträge'),
          ziel: { seite: 'kampagnen', parameter: { kampagne: id9(k.kampagne_id) } }, ziel_text: 'Öffnen' }, p === null ? {} : { fortschritt: p, label: p + ' %' }); });
      if (N(KPL.anzahl) > KZ.length) lk.push({ text: 'und ' + (N(KPL.anzahl) - KZ.length) + ' weitere', ziel: { seite: 'kampagnen' }, ziel_text: 'Alle Kampagnen' });
      return { karte: { ziel: { seite: 'kampagnen' }, ziel_text: 'Kampagnen öffnen', titel: 'Laufende Kampagnen', info: 'Fortschritt nach Laufzeit und gelieferten Beiträgen.', leer: 'Keine laufenden Kampagnen.', eintraege: lk } }; },
    // Neue Inhalte (seit gestern) und „Diese Woche“. Ohne neue Beiträge steht der Satz grau als Leertext wie bei den anderen Karten (Stefan 21.10.2026, 19:44).
    'talents-neue-inhalte': () => { if (!TKD) return null; const NB = ob(TKD.neue_beitraege) || {}, WO = ob(TKD.woche) || {};
      const neu = N(NB.anzahl) > 0 || N(NB.storys) > 0;
      const ni = (neu ? [{ text: String(NB.text || '') + (N(NB.storys) > 0 ? ', dazu ' + zahlWort(N(NB.storys), 'Story', 'Storys') : '') }] : [])
        .concat(L(WO.zeilen).filter(z => id9(z.talent_id) !== null).slice(0, 2).map(z => ({ fett: String(WO.titel || 'Diese Woche') + ':', text: String(z.anzeigename || ''),
          trend: { text: String(z.text || ''), richtung: z.richtung === 'runter' ? 'runter' : 'hoch' }, ziel: { seite: 'talent', parameter: { id: id9(z.talent_id) } }, ziel_text: 'Öffnen' })));
      const satz = String(NB.text || 'Keine neuen Beiträge seit gestern');
      return { karte: Object.assign({ ziel: { seite: 'talents' }, ziel_text: 'Talents öffnen', titel: 'Neue Inhalte', info: 'Seit gestern veröffentlicht.' + (TKD.leer_hinweis ? ' ' + String(TKD.leer_hinweis) : ''), leer: satz, eintraege: ni },
        !neu && ni.length ? { unter: satz } : {}) }; },
    // Zahlenkacheln anderer Pakete aus denselben Quellen wie die Kacheln (ally_web_arbeit, Kampagnen-Kennzahlen)
    'kampagnen-stand': () => { if (!KP) return null; const l = N(KP.laufend), ue = N(KP.ueberfaellig), d7 = N(KP.deadlines_7), fr = N(KP.freigaben_offen);
      return { kennzahlen: [{ label: 'Kampagnen', wert: String(l), neben: [ue ? zahlWort(ue, 'Deadline überfällig', 'Deadlines überfällig') : '', d7 ? zahlWort(d7, 'Deadline', 'Deadlines') + ' in 7 Tagen' : '',
        fr ? zahlWort(fr, 'Freigabe offen', 'Freigaben offen') : ''].filter(Boolean).join(' · ') || (l === 1 ? 'läuft gerade' : 'laufen gerade'), ton: ue > 0 ? 'warn' : '', ziel: { seite: 'kampagnen' }, ziel_text: 'Kampagnen öffnen',
        details: KPL ? { art: 'zeilen', unter: 'Die 3 neuesten laufenden Kampagnen', leer: 'Keine laufenden Kampagnen.', zeilen: L(KPL.zeilen).slice().sort((a, b) => String(b.von_iso || '').localeCompare(String(a.von_iso || ''))).slice(0, 3)
          .map(k => ({ fett: String(k.titel || 'Kampagne'), text: 'bis ' + String(k.bis || '–'), neben: zahlWort(N(k.anzahl_beitraege), 'Beitrag', 'Beiträge') })) } : undefined }] }; },
    'mails-stand': () => { const m = ob(A.mails); if (!m || N(m.postfaecher) <= 0 || !m.entwuerfe) return null; const n = N(m.angebote);
      return { kennzahlen: [{ label: 'Antwortvorschläge', wert: String(n), neben: n === 1 ? 'Antwortvorschlag offen' : 'offen im Mail-Assistenten', ziel: { seite: 'mail-assistent' }, ziel_text: 'Mail-Assistent öffnen',
        details: Array.isArray(DE.vorschlaege) ? Object.assign(eintraege(DE.vorschlaege, 'Keine offenen Antwortvorschläge.'), { unter: 'Die 3 neuesten offenen Antwortvorschläge' }) : undefined }] }; },
    'belege-stand': () => { const b = ob(A.belege); if (!b) return null; const neu = N(b.neu), kl = N(b.klaerungen), fe = N(b.fehler);
      return { kennzahlen: [{ label: 'Belege', wert: String(neu), neben: b.laeuft ? 'Wird gerade verbucht' : [neu === 1 ? 'neuer Beleg' : 'neue Belege', kl ? zahlWort(kl, 'offene Frage', 'offene Fragen') : '',
        fe ? zahlWort(fe, 'Fehler', 'Fehler') : ''].filter(Boolean).join(' · '), ton: fe > 0 ? 'warn' : '', ziel: { seite: 'belege' }, ziel_text: 'Belege öffnen',
